def write(path,text):path.write_text(text,encoding='utf-8',newline='\n')
def replace_file(rel,pairs):
    p=ROOT/rel;s=p.read_text(encoding='utf-8')
    for old,new in pairs:s=s.replace(old,new)
    write(p,s)

for name,(node,label,body) in DATA.items():
    p=ROOT/f'ia/wireframes/{name}.md'
    text=f'''# {name} — {label}

**Размер:** desktop 1920×1080 px.
**Статус:** отрисовано и проверено. [Открыть Figma]({BASE}{node}).
**Основание:** 21 сентября 2026 пользователь поручил немедленно нарисовать предложенные экраны проектов, исследований, настройки и запуска. Повторных апрувов не требуется.

## Структура и поведение

{body}
## Границы макета

Редактируемый low-fi с Auto Layout, Inter Regular/Medium и согласованной монохромной палитрой. Данные искусственные, кнопки не подключены к работающему сервису. Альтернативные состояния описаны выше; кроме явно показанного состояния, отдельные фреймы для них не создавались. Метод привязки целей, правила попыток и хранения не меняются этим макетом.

Воспроизводимая сборка: `execution/build_project_wireframes.py`. Размещение: Dashboard → UX-Lab · Wireframes → Wireframes — Projects & Launch.
'''
    if p.exists() and p.read_text(encoding='utf-8')!=text:raise FileExistsError(p)
    write(p,text)

replace_file('prd.md', [('Создать, назвать и вновь открыть исследование с его настройками и результатами. Отдельная сложная иерархия проектов для этого не требуется.', 'Создать проект с названием и необязательным описанием; внутри проекта создать, назвать и вновь открыть исследование с его настройками и результатами. Иерархия: проект → исследования → сценарии. Проекты не вложены друг в друга; права двух коллег одинаковы. Уточнение пользователя от 21 сентября 2026.')])
p=ROOT/'prd.md';s=p.read_text(encoding='utf-8')
if '## Уточнение от 21 сентября 2026: проекты' not in s:
    s+='''\n## Уточнение от 21 сентября 2026: проекты

По поручению пользователя добавлен первый уровень «Проекты». Проект группирует исследования одного продукта; исследование содержит режим, задания, критерии, подключение, участников и результаты. Projects — начальная рабочая точка коллеги после входа. Studies теперь является страницей конкретного проекта. Создание проекта → пустой Studies → создание исследования → StudySetup → Launch → ResultsOverview. Иерархия проектов включена в текущую проработку; остальные функции первой версии сохранены.

При создании обязательны название проекта и название исследования; описание проекта необязательно. Отдельные права, вложенные проекты, архивирование и удаление не добавлены. Статусы в макетах «Черновик / Идёт сбор / Завершено» — предложенные отображения, детали D03 ещё открыты. Ссылка приглашения выдаётся после успешного запуска, не после сохранения черновика. [Новые wireframes](ia/wireframes/projects-delivery.md).
'''
    write(p,s)
