        target='projects-delivery.md' if rel=='ia/wireframes/README.md' else '../wireframes/projects-delivery.md' if rel=='ia/flows/README.md' else 'wireframes/projects-delivery.md'
        s+=f'\n## Уточнение 21 сентября 2026\n\nДобавлена иерархия проектов и четыре wireframe. [Актуальные экраны и границы обновления]({target}). Старые схемы Figma — версия до Projects; текст sitemap и flow запуска обновлён.\n'
        write(p,s)
